class SuperElevationUI(tk.Tk):
    def __init__(self) -> None:
        super().__init__()
        self.title("Superelevation Calculator")
        self.last_results: dict | None = None
        self._auto_job: str | None = None
        self._suspend_auto = False
        self._current_project_path: str | None = None
        self.last_meta = {}
        self.curves: list[dict] = []

        self.vars = {
            "pc": tk.StringVar(),
            "pt": tk.StringVar(),
            "speed": tk.StringVar(),
            "radius": tk.StringVar(),
            "alignment_name": tk.StringVar(),
            "curve_name": tk.StringVar(),
            "curve_direction": tk.StringVar(value="left"),
            "facility": tk.StringVar(value="centerline"),
            "area": tk.StringVar(value="rural"),
            "lane_width": tk.StringVar(value="12"),
            "lanes_rotated": tk.StringVar(value="2"),
            "e_manual": tk.StringVar(),
            "friction": tk.StringVar(),
            "rel_grad": tk.StringVar(),
            "normal_crown": tk.StringVar(value="0.02"),
            "Lr_manual": tk.StringVar(),
            "Lt_manual": tk.StringVar(),
            "station_format": tk.BooleanVar(value=True),
            "auto_open_pdf": tk.BooleanVar(value=True),
            "lookup_station": tk.StringVar(),
            "lookup_super": tk.StringVar(),
        }

        self._build_layout()
        self._set_initial_size()
        self._setup_auto_handlers()
        self._startup_prompt()
        self.protocol("WM_DELETE_WINDOW", self._on_close)

    def _set_initial_size(self) -> None:
        self.update_idletasks()
        req_w = self.winfo_reqwidth()
        req_h = self.winfo_reqheight()
        padding_w = 40
        padding_h = 40
        target_w = req_w + padding_w
        target_h = req_h + padding_h
        self.minsize(target_w, target_h)
        self.geometry(f"{target_w}x{target_h}")

    def _build_layout(self) -> None:
        root = ttk.Frame(self, padding=12)
        root.grid(row=0, column=0, sticky="nsew")
        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)

        inputs = ttk.LabelFrame(root, text="Inputs")
        inputs.grid(row=0, column=0, sticky="nsew", padx=(0, 12))
        root.columnconfigure(0, weight=1)
        root.rowconfigure(0, weight=1)

        output = ttk.LabelFrame(root, text="Results")
        output.grid(row=0, column=1, sticky="nsew")
        root.columnconfigure(1, weight=1)

        inputs_canvas = tk.Canvas(inputs, highlightthickness=0)
        inputs_scroll = ttk.Scrollbar(inputs, orient="vertical", command=inputs_canvas.yview)
        inputs_canvas.configure(yscrollcommand=inputs_scroll.set)
        inputs_canvas.grid(row=0, column=0, sticky="nsew")
        inputs_scroll.grid(row=0, column=1, sticky="ns")
        inputs.columnconfigure(0, weight=1)
        inputs.rowconfigure(0, weight=1)

        input_body = ttk.Frame(inputs_canvas)
        window_id = inputs_canvas.create_window((0, 0), window=input_body, anchor="nw")

        def _on_canvas_configure(event: tk.Event) -> None:
            inputs_canvas.itemconfigure(window_id, width=event.width)

        def _on_frame_configure(_: tk.Event) -> None:
            inputs_canvas.configure(scrollregion=inputs_canvas.bbox("all"))

        def _on_mousewheel(event: tk.Event) -> None:
            if event.delta:
                inputs_canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            else:
                inputs_canvas.yview_scroll(-1 if event.num == 4 else 1, "units")

        def _bind_mousewheel(_: tk.Event) -> None:
            inputs_canvas.bind_all("<MouseWheel>", _on_mousewheel)
            inputs_canvas.bind_all("<Button-4>", _on_mousewheel)
            inputs_canvas.bind_all("<Button-5>", _on_mousewheel)

        def _unbind_mousewheel(_: tk.Event) -> None:
            inputs_canvas.unbind_all("<MouseWheel>")
            inputs_canvas.unbind_all("<Button-4>")
            inputs_canvas.unbind_all("<Button-5>")

        input_body.bind("<Configure>", _on_frame_configure)
        inputs_canvas.bind("<Configure>", _on_canvas_configure)
        input_body.bind("<Enter>", _bind_mousewheel)
        input_body.bind("<Leave>", _unbind_mousewheel)
        inputs_canvas.bind("<Enter>", _bind_mousewheel)
        inputs_canvas.bind("<Leave>", _unbind_mousewheel)

        header_font = tkfont.Font(family="TkDefaultFont", size=12, weight="bold")

        ttk.Label(input_body, text="Alignment (Chain) Name", font=header_font).grid(
            row=0, column=0, sticky="w", padx=6, pady=(6, 2)
        )
        ttk.Entry(input_body, textvariable=self.vars["alignment_name"], font=header_font).grid(
            row=0, column=1, sticky="ew", padx=6, pady=(6, 2)
        )
        ttk.Label(input_body, text="Curve Name", font=header_font).grid(
            row=1, column=0, sticky="w", padx=6, pady=2
        )
        ttk.Entry(input_body, textvariable=self.vars["curve_name"], font=header_font).grid(
            row=1, column=1, sticky="ew", padx=6, pady=2
        )

        ttk.Label(input_body, text="Saved Curves").grid(row=2, column=0, sticky="w", padx=6, pady=(2, 6))
        self.curve_listbox = tk.Listbox(input_body, height=4)
        self.curve_listbox.grid(row=2, column=1, sticky="ew", padx=6, pady=(2, 6))
        curve_buttons = ttk.Frame(input_body)
        curve_buttons.grid(row=3, column=0, columnspan=2, sticky="w", padx=6, pady=(0, 8))
        ttk.Button(curve_buttons, text="Save Curve", command=self._add_curve).grid(
            row=0, column=0, padx=(0, 8)
        )
        ttk.Button(curve_buttons, text="Update Selected", command=self._update_selected_curve).grid(
            row=0, column=1, padx=(0, 8)
        )
        ttk.Button(curve_buttons, text="Remove Selected", command=self._remove_curve).grid(
            row=0, column=2
        )
        self.curve_listbox.bind("<<ListboxSelect>>", self._load_curve_selection)

        row_offset = 4
        fields = [
            ("PC station *", "pc"),
            ("PT station (optional)", "pt"),
            ("Design speed (mph) *", "speed"),
            ("Curve radius (ft) *", "radius"),
            ("Facility / rotation (auto ok)", "facility"),
            ("Curve direction (auto ok)", "curve_direction"),
            ("Area type (auto ok)", "area"),
            ("Lane width (ft, auto ok)", "lane_width"),
            ("Lanes rotated (auto ok)", "lanes_rotated"),
            ("Superelevation rate e (auto)", "e_manual"),
            ("Side friction f (auto)", "friction"),
            ("Relative gradient (auto)", "rel_grad"),
            ("Normal crown (auto)", "normal_crown"),
            ("Runoff length Lr (auto)", "Lr_manual"),
            ("Tangent runout Lt (auto)", "Lt_manual"),
            ("Lookup station (optional)", "lookup_station"),
            ("Lookup super (optional)", "lookup_super"),
        ]

        for row, (label, key) in enumerate(fields, start=row_offset):
            ttk.Label(input_body, text=label).grid(row=row, column=0, sticky="w", padx=6, pady=4)
            if key == "facility":
                widget = ttk.Combobox(
                    input_body,
                    textvariable=self.vars[key],
                    values=["centerline", "outside edge"],
                    state="readonly",
                )
            elif key == "curve_direction":
                widget = ttk.Combobox(
                    input_body,
                    textvariable=self.vars[key],
                    values=["left", "right"],
                    state="readonly",
                )
            elif key == "speed":
                speeds = [str(v) for v in range(15, 85, 5)]
                widget = ttk.Combobox(
                    input_body,
                    textvariable=self.vars[key],
                    values=speeds,
                    state="readonly",
                )
            elif key == "area":
                widget = ttk.Combobox(
                    input_body,
                    textvariable=self.vars[key],
                    values=["rural", "urban", "local"],
                    state="readonly",
                )
            else:
                widget = ttk.Entry(input_body, textvariable=self.vars[key], width=24)
            widget.grid(row=row, column=1, sticky="ew", padx=6, pady=4)

        input_body.columnconfigure(1, weight=1)

        action_row = len(fields) + row_offset
        check_row = ttk.Frame(input_body)
        check_row.grid(row=action_row, column=0, columnspan=2, sticky="w", padx=6, pady=6)
        ttk.Checkbutton(
            check_row,
            text="Display stations in highway format",
            variable=self.vars["station_format"],
        ).grid(row=0, column=0, padx=(0, 12))
        ttk.Checkbutton(
            check_row,
            text="Auto-open PDF after export",
            variable=self.vars["auto_open_pdf"],
        ).grid(row=0, column=1)

        button_row = ttk.Frame(input_body)
        button_row.grid(row=action_row + 1, column=0, columnspan=2, sticky="w", padx=6, pady=6)
        ttk.Button(button_row, text="Save Curve", command=self._add_curve).grid(row=0, column=0, padx=(0, 8))
        ttk.Button(button_row, text="New Project", command=lambda: self._new_project(prompt_for_path=True)).grid(
            row=0, column=1, padx=(0, 8)
        )
        ttk.Button(button_row, text="Save Project", command=self._save_project).grid(
            row=0, column=2, padx=(0, 8)
        )
        ttk.Button(button_row, text="Load Project", command=self._load_project).grid(
            row=0, column=3, padx=(0, 8)
        )
        ttk.Button(button_row, text="Compute", command=self._compute).grid(row=1, column=0, padx=(0, 8), pady=(6, 0))
        ttk.Button(button_row, text="Lookup", command=self._compute_lookup).grid(row=1, column=1, padx=(0, 8), pady=(6, 0))
        ttk.Button(button_row, text="Clear", command=self._clear).grid(row=1, column=2, padx=(0, 8), pady=(6, 0))
        ttk.Button(button_row, text="Export PDF", command=self._export_pdf).grid(row=1, column=3, padx=(0, 0), pady=(6, 0))

        ttk.Label(
            input_body,
            text=(
                "* Required for auto-compute.\n"
                "Auto-compute rules (leave blank):\n"
                "- e: rural tables; local (SE-1) table for V<=45; urban tables for V<=45 or V=50 center/edge; else formula\n"
                "- f: default speed-based table (if formula used)\n"
                "- Lr: table override if available, else Eq. 3-4-1\n"
                "- Lt: table override if available, else Eq. 3-4-1\n"
                "- Extra width: local (SE-1) table if applicable\n"
                "- Relative gradient: Table 3-4-C\n"
                "- Lane width/lanes/normal crown use defaults shown"
            ),
            justify="left",
        ).grid(row=action_row + 2, column=0, columnspan=2, sticky="w", padx=6, pady=4)

        self.output_font = tkfont.Font(family="Arial", size=11)
        self.table_font = tkfont.nametofont("TkFixedFont").copy()
        self.table_font.configure(size=11)
        output_top = ttk.Frame(output)
        output_top.grid(row=0, column=0, sticky="nsew")
        output_bottom = ttk.Frame(output)
        output_bottom.grid(row=1, column=0, sticky="nsew")
        output.columnconfigure(0, weight=1)
        output.rowconfigure(0, weight=1)
        output.rowconfigure(1, weight=0)

        self.output_left = tk.Text(
            output_top,
            height=30,
            wrap="word",
            state="disabled",
            font=self.output_font,
        )
        separator = ttk.Separator(output_top, orient="vertical")
        self.output_right = tk.Text(
            output_top,
            height=30,
            wrap="word",
            state="disabled",
            font=self.output_font,
        )
        self.output_left.grid(row=0, column=0, sticky="nsew", padx=(6, 3), pady=6)
        separator.grid(row=0, column=1, sticky="ns")
        self.output_right.grid(row=0, column=2, sticky="nsew", padx=(3, 6), pady=6)
        output_top.columnconfigure(0, weight=1)
        output_top.columnconfigure(1, weight=0)
        output_top.columnconfigure(2, weight=1)
        output_top.rowconfigure(0, weight=1)

        self.output_table = tk.Text(
            output_bottom,
            height=12,
            wrap="none",
            state="disabled",
            font=self.table_font,
        )
        self.output_table.grid(row=0, column=0, sticky="nsew", padx=6, pady=(0, 6))
        output_bottom.columnconfigure(0, weight=1)
        output_bottom.rowconfigure(0, weight=1)

    def _clear(self) -> None:
        self._suspend_auto = True
        for key, var in self.vars.items():
            if isinstance(var, tk.BooleanVar):
                var.set(True)
            else:
                var.set("")
        self.vars["facility"].set("centerline")
        self.vars["curve_direction"].set("left")
        self.vars["area"].set("rural")
        self.vars["lane_width"].set("12")
        self.vars["lanes_rotated"].set("2")
        self.vars["normal_crown"].set("0.02")
        self.vars["lookup_station"].set("")
        self.vars["lookup_super"].set("")
        self._write_output_sections([], [], [])
        self.last_results = None
        self.last_meta = {}
        self._suspend_auto = False

    def _write_output_sections(
        self, left_lines: list[str], right_lines: list[str], table_lines: list[str]
    ) -> None:
        bold_font = self.output_font.copy()
        bold_font.configure(weight="bold")

        def render_widget(widget: tk.Text, lines: list[str]) -> None:
            widget.configure(state="normal")
            widget.delete("1.0", "end")
            widget.tag_configure("header", font=bold_font)
            widget.tag_configure("key", font=bold_font, foreground="#0b5")
            widget.tag_configure("station", font=bold_font, foreground="#1565c0")
            if lines:
                widget.insert("1.0", "\n".join(lines))
                self._apply_highlights(widget)
            widget.configure(state="disabled")

        render_widget(self.output_left, left_lines)
        render_widget(self.output_right, right_lines)

        self.output_table.configure(state="normal")
        self.output_table.delete("1.0", "end")
        if table_lines:
            self.output_table.insert("1.0", "\n".join(table_lines))
        self.output_table.configure(state="disabled")

    def _apply_highlights(self, widget: tk.Text) -> None:
        important_prefixes = (
            "Superelevation rate e:",
            "Runoff length Lr:",
            "Tangent runout Lt:",
            "Extra width",
        )
        station_prefixes = (
            "Point of normal crown",
            "Point of reverse crown",
            "Full super",
            "PT:",
        )
        for prefix in important_prefixes:
            self._tag_line(widget, prefix, "key")
        for prefix in station_prefixes:
            self._tag_line(widget, prefix, "station")
        self._tag_line(widget, "--- Inputs ---", "header")
        self._tag_line(widget, "--- Results ---", "header")
        self._tag_line(widget, "--- Lookup ---", "header")

    def _tag_line(self, widget: tk.Text, prefix: str, tag: str) -> None:
        start = "1.0"
        while True:
            idx = widget.search(prefix, start, stopindex="end")
            if not idx:
                break
            line_end = widget.index(f"{idx} lineend")
            widget.tag_add(tag, idx, line_end)
            start = line_end

    def _compute(self, show_errors: bool = True) -> None:
        try:
            alignment_name = self.vars["alignment_name"].get().strip() or "n/a"
            curve_name = self.vars["curve_name"].get().strip() or "n/a"
            if self.vars["area"].get().strip().lower().startswith("local"):
                self.vars["facility"].set("centerline")
            results = Super.calculate_superelevation(
                self.vars["pc"].get(),
                self.vars["pt"].get(),
                self.vars["speed"].get(),
                self.vars["radius"].get(),
                self.vars["facility"].get(),
                self.vars["area"].get(),
                self.vars["lane_width"].get(),
                self.vars["lanes_rotated"].get(),
                self.vars["e_manual"].get(),
                self.vars["friction"].get(),
                self.vars["rel_grad"].get(),
                self.vars["normal_crown"].get(),
                self.vars["Lr_manual"].get(),
                self.vars["Lt_manual"].get(),
            )
            left_lines, right_lines, table_lines = self._build_display_blocks(results)
            self._write_output_sections(left_lines, right_lines, table_lines)
            self.last_results = results
            self.last_meta = {
                "alignment_name": alignment_name,
                "curve_name": curve_name,
                "curve_direction": self.vars["curve_direction"].get(),
            }
        except ValueError as exc:
            if show_errors:
                messagebox.showerror("Input Error", str(exc))

    def _build_output_lines(self, results: dict) -> list[str]:
        core_lines, table_lines = self._build_output_sections(results)
        return core_lines + table_lines

    def _build_display_blocks(
        self, results: dict, lookup_lines: list[str] | None = None
    ) -> tuple[list[str], list[str], list[str]]:
        core_lines, table_lines = self._build_output_sections(results)
        try:
            results_idx = core_lines.index("--- Results ---")
        except ValueError:
            results_idx = len(core_lines)

        left_lines = core_lines[:results_idx]
        right_lines = core_lines[results_idx:]
        if lookup_lines:
            if right_lines and right_lines[-1].strip() != "":
                right_lines.append("")
            right_lines.extend(lookup_lines)
        return left_lines, right_lines, table_lines

    def _build_output_sections(self, results: dict) -> tuple[list[str], list[str]]:
        alignment_name = self.vars["alignment_name"].get().strip() or "n/a"
        curve_name = self.vars["curve_name"].get().strip() or "n/a"
        direction = self.vars["curve_direction"].get()
        station_format = self.vars["station_format"].get()
        inputs = results.get("inputs", {}) or {}
        segments = results.get("segments", {}) or {}

        def fmt_station(value: float | None) -> str:
            if value is None:
                return "n/a"
            return Super.format_station(value, station_format)

        core_lines: list[str] = []
        core_lines.append("Superelevation Transition Summary")
        core_lines.append("")
        core_lines.append("--- Inputs ---")
        core_lines.append(f"Alignment (chain) name: {alignment_name}")
        core_lines.append(f"Curve name: {curve_name}")
        core_lines.append(f"Curve direction: {direction}")
        core_lines.append(f"PC station: {inputs.get('pc', '')}")
        core_lines.append(f"PT station: {inputs.get('pt', '') or 'n/a'}")
        core_lines.append(f"Design speed: {inputs.get('speed_mph', '')} mph")
        core_lines.append(f"Curve radius: {inputs.get('radius_ft', '')} ft")
        core_lines.append(f"Facility / rotation: {inputs.get('facility', '')}")
        core_lines.append(f"Area type: {inputs.get('area_type', '')}")
        core_lines.append(f"Lane width: {inputs.get('lane_width_ft', '')} ft")
        core_lines.append(f"Lanes rotated: {inputs.get('lanes_rotated', '')}")
        core_lines.append(
            f"Manual e: {inputs.get('e_manual', '') if inputs.get('e_manual') is not None else 'auto'}"
        )
        core_lines.append(
            f"Manual Lr: {inputs.get('Lr_manual', '') if inputs.get('Lr_manual') is not None else 'auto'} ft"
        )
        core_lines.append(
            f"Manual Lt: {inputs.get('Lt_manual', '') if inputs.get('Lt_manual') is not None else 'auto'} ft"
        )
        core_lines.append(f"Normal crown: {inputs.get('normal_crown', '')} ft/ft")
        core_lines.append(f"Relative gradient input: {inputs.get('relative_gradient_input', '') or 'auto'}")
        core_lines.append(f"Side friction input: {inputs.get('friction_input', '') or 'auto'}")
        core_lines.append("")

        core_lines.append("--- Givens ---")
        core_lines.append(f"Facility case: {results['facility'] or 'n/a'}")
        if results["pt_ft"] is not None:
            core_lines.append(f"PT: {fmt_station(results['pt_ft'])}")
        core_lines.append(f"e_max used: {results['e_max']:.2f} ft/ft")
        core_lines.append(f"e source: {results['e_source']}")
        if results["friction"] is not None:
            core_lines.append(f"Side friction factor f: {results['friction']:.4f}")
        if results.get("friction_note"):
            core_lines.append(f"Note: {results['friction_note']}")
        if results.get("e_note"):
            core_lines.append(f"Note: {results['e_note']}")
        if results.get("runoff_note"):
            core_lines.append(f"Note: {results['runoff_note']}")
        core_lines.append(
            f"Lanes rotated used: {results['lanes_used']:.1f} (n1={results['n1']:.1f}, bw={results['bw']:.3f})"
        )
        if results.get("lanes_note"):
            core_lines.append(f"Note: {results['lanes_note']}")
        core_lines.append(f"Relative gradient used: {results['relative_gradient']:.4f} ft/ft")
        if results.get("rel_grad_note"):
            core_lines.append(f"Note: {results['rel_grad_note']}")
        core_lines.append(
            f"Table 3-4-A radii (Rnc, Rrc): {results['r_normal']:.0f} ft, {results['r_reverse']:.0f} ft"
        )
        if results.get("r_note"):
            core_lines.append(f"Note: {results['r_note']}")
        core_lines.append(f"Crown condition by Table 3-4-A: {results['crown_state']}")
        core_lines.append("")

        core_lines.append("--- Results ---")
        core_lines.append(f"Superelevation rate e: {results['e']:.4f} ft/ft")
        core_lines.append(f"Design speed: {inputs.get('speed_mph', '')} mph")
        core_lines.append(f"Runoff length Lr: {results['Lr']:.2f} ft")
        core_lines.append(f"Tangent runout Lt: {results['Lt']:.2f} ft")
        core_lines.append(f"Total transition (Lt + Lr): {segments.get('total_transition', 0.0):.2f} ft")
        if results.get("extra_width", 0.0) > 0:
            core_lines.append(f"Extra width (inside of curve): {results['extra_width']:.2f} ft")
            if results.get("extra_width_note"):
                core_lines.append(f"Note: {results['extra_width_note']}")
        core_lines.append(f"Approx. 0.7Lr: {segments.get('approx_0p7L', 0.0):.2f} ft")
        core_lines.append(f"Approx. 0.3Lr: {segments.get('approx_0p3L', 0.0):.2f} ft")
        core_lines.append("")

        core_lines.append("Station references")
        core_lines.append(
            f"Point of normal crown (start of tangential runout): {fmt_station(results['pnc_ft'])}"
        )
        core_lines.append(f"Point of reverse crown (PC - 0.7L): {fmt_station(results['reverse_crown_ft'])}")
        core_lines.append(f"Full super (PC + 0.3L): {fmt_station(results['full_super_ft'])}")
        if results["pt_ft"] is not None:
            core_lines.append(f"Full super (PT - 0.3L): {fmt_station(results['full_super_out_ft'])}")
            core_lines.append(
                f"Point of reverse crown (PT + 0.7L): {fmt_station(results['reverse_crown_out_ft'])}"
            )
            core_lines.append(
                f"Point of normal crown (end of tangential runout): {fmt_station(results['pnc_out_ft'])}"
            )
        core_lines.append("")

        left_rows, right_rows = self._build_lane_rows_for_gui(results, direction, station_format)
        table_lines: list[str] = []
        table_lines.extend(self._format_lane_table("Left Lane", left_rows))
        table_lines.append("")
        table_lines.extend(self._format_lane_table("Right Lane", right_rows))
        return core_lines, table_lines

    def _build_lane_rows_for_gui(
        self, results: dict, direction: str, station_format: bool
    ) -> tuple[list[dict], list[dict]]:
        def lane_signs(local_direction: str) -> tuple[int, int, str, int]:
            sup_sign = 1 if local_direction.strip().lower().startswith("r") else -1
            return -1, 1, ("left" if sup_sign == 1 else "right"), sup_sign

        def fmt_station(value: float | None) -> str:
            if value is None:
                return "n/a"
            return Super.format_station(value, station_format)

        left_sign, right_sign, runout_lane, sup_sign = lane_signs(direction)
        L = results.get("Lr", 0.0)
        Lt = results.get("Lt", 0.0)
        e = results.get("e", 0.0)
        normal_crown = results.get("inputs", {}).get("normal_crown", 0.02)
        reverse_crown = results.get("reverse_crown_ft", 0.0)
        reverse_crown_out = results.get("reverse_crown_out_ft")

        pc = reverse_crown + 0.7 * L
        full_super_pc = results.get("full_super_ft", 0.0)
        full_super_pt = results.get("full_super_out_ft")
        pt = None
        if reverse_crown_out is not None:
            pt = reverse_crown_out - 0.7 * L

        nc_pct = normal_crown * 100.0
        e_pct = e * 100.0
        e70_pct = e_pct * 0.7

        reverse_crown_case = (
            str(results.get("crown_state", "")).lower().startswith("reverse")
            or str(results.get("e_source", "")).lower().startswith("reverse")
        )
        outside_lane = "right" if direction.strip().lower().startswith("r") else "left"

        def make_row(label: str, station: float | None, slope: float, note: str) -> dict:
            return {
                "label": label,
                "station": fmt_station(station),
                "slope": f"{slope:.2f}",
                "note": note,
            }

        def lane_rows(sign: int, has_runout: bool, lane_name: str) -> list[dict]:
            normal_sign = left_sign if lane_name == "left" else right_sign
            rows: list[dict] = []
            if reverse_crown_case:
                final_slope = (right_sign if outside_lane == "right" else left_sign) * nc_pct
                is_non_rotating = lane_name == outside_lane
                start_station = reverse_crown - Lt
                end_station = None
                if reverse_crown_out is not None:
                    end_station = reverse_crown_out + Lt

                if is_non_rotating:
                    rows.append(
                        make_row(
                            "NC",
                            start_station,
                            final_slope,
                            "Sta = PC - 0.7L - Lt (Start rotation)",
                        )
                    )
                    rows.append(make_row("PC", pc, final_slope, "70% super"))
                    rows.append(make_row("FULL SUPER", full_super_pc, final_slope, "Sta = PC + 0.3L"))
                    if pt is not None and full_super_pt is not None:
                        rows.append(make_row("FULL SUPER", full_super_pt, final_slope, "Sta = PT - 0.3L"))
                        rows.append(make_row("PT", pt, final_slope, "70% super"))
                    if end_station is not None:
                        rows.append(make_row("NC", end_station, final_slope, "Sta = PT + 0.7L + Lt"))
                    return rows

                rows.append(
                    make_row(
                        "NC",
                        start_station,
                        sign * nc_pct,
                        "Sta = PC - 0.7L - Lt (Start rotation)",
                    )
                )
                rows.append(make_row("0%", reverse_crown, 0.0, "Sta = PC - 0.7L"))
                rows.append(make_row("PC", pc, final_slope * 0.7, "70% super"))
                rows.append(make_row("FULL SUPER", full_super_pc, final_slope, "Sta = PC + 0.3L"))
                if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                    rows.append(make_row("FULL SUPER", full_super_pt, final_slope, "Sta = PT - 0.3L"))
                    rows.append(make_row("PT", pt, final_slope * 0.7, "70% super"))
                    rows.append(make_row("0%", reverse_crown_out, 0.0, "Sta = PT + 0.7L"))
                    rows.append(
                        make_row(
                            "NC",
                            reverse_crown_out + Lt,
                            sign * nc_pct,
                            "0% + runout (Normal crown)",
                        )
                    )
                return rows

            if has_runout:
                rows.append(
                    make_row(
                        "NC",
                        reverse_crown - Lt,
                        normal_sign * nc_pct,
                        "Sta = PC - 0.7L - Lt (Start rotation)",
                    )
                )
                rows.append(make_row("0%", reverse_crown, 0.0, "Sta = PC - 0.7L"))
                rows.append(
                    make_row(
                        "2%",
                        reverse_crown + Lt,
                        sup_sign * nc_pct,
                        "Sta = PC - 0.7L + Lt",
                    )
                )
            else:
                rows.append(
                    make_row(
                        "NC",
                        reverse_crown + Lt,
                        normal_sign * nc_pct,
                        "Sta = PC - 0.7L + Lt (Start rotation)",
                    )
                )

            rows.append(make_row("PC", pc, sup_sign * e70_pct, "70% super"))
            rows.append(make_row("FULL SUPER", full_super_pc, sup_sign * e_pct, "Sta = PC + 0.3L"))
            if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                rows.append(make_row("FULL SUPER", full_super_pt, sup_sign * e_pct, "Sta = PT - 0.3L"))
                rows.append(make_row("PT", pt, sup_sign * e70_pct, "70% super"))
                if has_runout:
                    rows.append(make_row("0%", reverse_crown_out, 0.0, "Sta = PT + 0.7L"))
                    rows.append(
                        make_row(
                            "NC",
                            reverse_crown_out + Lt,
                            normal_sign * nc_pct,
                            "0% + runout (Normal crown)",
                        )
                    )
                else:
                    rows.append(
                        make_row(
                            "NC",
                            reverse_crown_out - Lt,
                            normal_sign * nc_pct,
                            "Sta = PT + 0.7L - Lt",
                        )
                    )
            return rows

        left_rows = lane_rows(left_sign, runout_lane == "left", "left")
        right_rows = lane_rows(right_sign, runout_lane == "right", "right")
        return left_rows, right_rows

    def _format_lane_table(self, title: str, rows: list[dict]) -> list[str]:
        header = f"{'Point':<14}{'Station':<16}{'Slope (%)':<10}Note"
        divider = "-" * max(len(header), 64)
        lines = [title, header, divider]
        for row in rows:
            lines.append(f"{row['label']:<14}{row['station']:<16}{row['slope']:>10}  {row['note']}")
        return lines

    def _lane_profile_points(self, results: dict, direction: str) -> dict[str, list[tuple[float, float]]]:
        def lane_signs_local(direction_val: str) -> tuple[int, int, str, int]:
            sup_sign = 1 if direction_val.strip().lower().startswith("r") else -1
            return -1, 1, ("left" if sup_sign == 1 else "right"), sup_sign

        left_sign, right_sign, runout_lane, sup_sign = lane_signs_local(direction)
        L = results.get("Lr", 0.0)
        Lt = results.get("Lt", 0.0)
        e = results.get("e", 0.0)
        normal_crown = results.get("inputs", {}).get("normal_crown", 0.02)
        reverse_crown = results.get("reverse_crown_ft", 0.0)
        reverse_crown_out = results.get("reverse_crown_out_ft")

        pc = reverse_crown + 0.7 * L
        full_super_pc = results.get("full_super_ft", 0.0)
        full_super_pt = results.get("full_super_out_ft")
        pt = None
        if reverse_crown_out is not None:
            pt = reverse_crown_out - 0.7 * L

        nc_pct = normal_crown * 100.0
        e_pct = e * 100.0
        e70_pct = e_pct * 0.7

        reverse_crown_case = (
            str(results.get("crown_state", "")).lower().startswith("reverse")
            or str(results.get("e_source", "")).lower().startswith("reverse")
        )
        outside_lane = "right" if direction.strip().lower().startswith("r") else "left"

        def lane_points(sign: int, has_runout: bool, lane_name: str) -> list[tuple[float, float]]:
            normal_sign = left_sign if lane_name == "left" else right_sign
            points: list[tuple[float, float]] = []
            if reverse_crown_case:
                final_slope = (right_sign if outside_lane == "right" else left_sign) * nc_pct
                is_non_rotating = lane_name == outside_lane
                start_station = reverse_crown - Lt
                end_station = None
                if reverse_crown_out is not None:
                    end_station = reverse_crown_out + Lt

                if is_non_rotating:
                    points.extend(
                        [
                            (start_station, final_slope),
                            (pc, final_slope),
                            (full_super_pc, final_slope),
                        ]
                    )
                    if pt is not None and full_super_pt is not None:
                        points.extend(
                            [
                                (full_super_pt, final_slope),
                                (pt, final_slope),
                            ]
                        )
                    if end_station is not None:
                        points.append((end_station, final_slope))
                    return points

                points.append((start_station, sign * nc_pct))
                points.append((reverse_crown, 0.0))
                points.append((pc, final_slope * 0.7))
                points.append((full_super_pc, final_slope))
                if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                    points.extend(
                        [
                            (full_super_pt, final_slope),
                            (pt, final_slope * 0.7),
                            (reverse_crown_out, 0.0),
                            (reverse_crown_out + Lt, sign * nc_pct),
                        ]
                    )
                return points

            if has_runout:
                points.extend(
                    [
                        (reverse_crown - Lt, normal_sign * nc_pct),
                        (reverse_crown, 0.0),
                        (reverse_crown + Lt, sup_sign * nc_pct),
                    ]
                )
            else:
                points.append((reverse_crown + Lt, normal_sign * nc_pct))

            points.extend(
                [
                    (pc, sup_sign * e70_pct),
                    (full_super_pc, sup_sign * e_pct),
                ]
            )
            if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                points.extend(
                    [
                        (full_super_pt, sup_sign * e_pct),
                        (pt, sup_sign * e70_pct),
                    ]
                )
                if has_runout:
                    points.extend(
                        [
                            (reverse_crown_out, 0.0),
                            (reverse_crown_out + Lt, normal_sign * nc_pct),
                        ]
                    )
                else:
                    points.append((reverse_crown_out - Lt, normal_sign * nc_pct))
            return points

        left_points = lane_points(left_sign, runout_lane == "left", "left")
        right_points = lane_points(right_sign, runout_lane == "right", "right")

        def normalize(points: list[tuple[float, float]]) -> list[tuple[float, float]]:
            cleaned = [(x, y) for x, y in points if x is not None]
            cleaned.sort(key=lambda p: p[0])
            return cleaned

        return {
            "left": normalize(left_points),
            "right": normalize(right_points),
        }

    def _compute_lookup(self) -> None:
        if not self.last_results:
            messagebox.showinfo("Lookup", "Run a calculation first.")
            return

        station_str = self.vars["lookup_station"].get().strip()
        super_str = self.vars["lookup_super"].get().strip()
        if not station_str and not super_str:
            messagebox.showinfo("Lookup", "Enter a station, a super value, or both.")
            return

        station_ft = None
        if station_str:
            try:
                station_ft = Super.parse_station(station_str)
            except ValueError:
                messagebox.showerror("Lookup", "Invalid lookup station.")
                return

        target_slope = None
        if super_str:
            try:
                raw = float(super_str)
            except ValueError:
                messagebox.showerror("Lookup", "Invalid lookup super value.")
                return
            target_slope = raw if abs(raw) > 1.0 else raw * 100.0

        points = self._lane_profile_points(self.last_results, self.vars["curve_direction"].get())
        reference_ft = station_ft
        if reference_ft is None:
            inputs = self.last_results.get("inputs", {})
            reference_ft = Super.parse_station(inputs.get("pc", "0"))

        def slope_at_station(point_list: list[tuple[float, float]], station: float) -> float:
            if not point_list:
                return 0.0
            if station <= point_list[0][0]:
                return point_list[0][1]
            if station >= point_list[-1][0]:
                return point_list[-1][1]
            for (x0, y0), (x1, y1) in zip(point_list, point_list[1:]):
                if x0 <= station <= x1 or x1 <= station <= x0:
                    if x1 == x0:
                        return y1
                    t = (station - x0) / (x1 - x0)
                    return y0 + (y1 - y0) * t
            return point_list[-1][1]

        def station_for_slope(point_list: list[tuple[float, float]], target: float, ref: float) -> float | None:
            candidates: list[float] = []
            for (x0, y0), (x1, y1) in zip(point_list, point_list[1:]):
                if y0 == y1 == target:
                    candidates.extend([x0, x1])
                elif (target - y0) * (target - y1) <= 0 and y0 != y1:
                    t = (target - y0) / (y1 - y0)
                    x = x0 + t * (x1 - x0)
                    candidates.append(x)
            if not candidates:
                return None
            return min(candidates, key=lambda x: abs(x - ref))

        lookup_lines = ["--- Lookup ---"]
        if station_ft is not None:
            lookup_lines.append(f"Lookup station: {Super.format_station(station_ft, True)}")
            for lane in ("left", "right"):
                slope = slope_at_station(points[lane], station_ft)
                lookup_lines.append(
                    f"{lane.title()} lane super: {slope:.2f}% ({slope/100.0:.4f} ft/ft)"
                )

        if target_slope is not None:
            lookup_lines.append(f"Lookup super: {target_slope:.2f}% ({target_slope/100.0:.4f} ft/ft)")
            for lane in ("left", "right"):
                station = station_for_slope(points[lane], target_slope, reference_ft or 0.0)
                if station is None:
                    lookup_lines.append(f"{lane.title()} lane station: n/a")
                else:
                    lookup_lines.append(
                        f"{lane.title()} lane station: {Super.format_station(station, True)}"
                    )

        left_lines, right_lines, table_lines = self._build_display_blocks(self.last_results, lookup_lines)
        self._write_output_sections(left_lines, right_lines, table_lines)

    def _load_curve_selection(self, _: tk.Event) -> None:
        selection = list(self.curve_listbox.curselection())
        if not selection:
            return
        idx = selection[0]
        if idx >= len(self.curves):
            return
        curve = self.curves[idx]
        results = curve.get("results")
        meta = curve.get("meta", {}) or {}
        if not results:
            return
        inputs = results.get("inputs", {}) or {}

        self._suspend_auto = True
        self.vars["alignment_name"].set(meta.get("alignment_name", ""))
        self.vars["curve_name"].set(meta.get("curve_name", ""))
        self.vars["curve_direction"].set(meta.get("curve_direction", "left"))
        self.vars["pc"].set(inputs.get("pc", ""))
        self.vars["pt"].set(inputs.get("pt", ""))
        self.vars["speed"].set(str(inputs.get("speed_mph", "")))
        self.vars["radius"].set(str(inputs.get("radius_ft", "")))
        self.vars["facility"].set(inputs.get("facility", "centerline"))
        self.vars["area"].set(inputs.get("area_type", "rural"))
        self.vars["lane_width"].set(str(inputs.get("lane_width_ft", "")))
        self.vars["lanes_rotated"].set(str(inputs.get("lanes_rotated", "")))
        self.vars["e_manual"].set("" if inputs.get("e_manual") is None else str(inputs.get("e_manual")))
        self.vars["friction"].set(inputs.get("friction_input", ""))
        self.vars["rel_grad"].set(inputs.get("relative_gradient_input", ""))
        self.vars["normal_crown"].set(str(inputs.get("normal_crown", "")))
        self.vars["Lr_manual"].set("" if inputs.get("Lr_manual") is None else str(inputs.get("Lr_manual")))
        self.vars["Lt_manual"].set("" if inputs.get("Lt_manual") is None else str(inputs.get("Lt_manual")))
        self._suspend_auto = False

        self.last_results = results
        self.last_meta = meta
        left_lines, right_lines, table_lines = self._build_display_blocks(results)
        self._write_output_sections(left_lines, right_lines, table_lines)
        self._schedule_auto_compute()

    def _setup_auto_handlers(self) -> None:
        for var in self.vars.values():
            var.trace_add("write", self._on_input_change)

    def _on_input_change(self, *_: object) -> None:
        if self._suspend_auto:
            return
        self._schedule_auto_compute()

    def _schedule_auto_compute(self) -> None:
        if self._auto_job:
            self.after_cancel(self._auto_job)
        self._auto_job = self.after(400, self._auto_compute)

    def _auto_compute(self) -> None:
        self._auto_job = None
        if self._suspend_auto:
            return
        if not self._required_fields_present():
            return
        try:
            self._compute(show_errors=False)
        except Exception:
            return

    def _required_fields_present(self) -> bool:
        return all(
            self.vars[key].get().strip()
            for key in ("pc", "speed", "radius")
        )

    def _startup_prompt(self) -> None:
        choice = messagebox.askyesno(
            "Start Project",
            "Load an existing project?",
        )
        if choice:
            self._load_project()
        else:
            self._new_project(prompt_for_path=True)

    def _prompt_project_path(self) -> str | None:
        directory = filedialog.askdirectory(title="Select Project Folder")
        if not directory:
            return None
        name = simpledialog.askstring("Project Name", "Enter a project name:")
        if not name:
            return None
        filename = f"{name}.json" if not name.lower().endswith(".json") else name
        return os.path.join(directory, filename)

    def _new_project(self, prompt_for_path: bool = False) -> None:
        self._suspend_auto = True
        self._clear()
        self.curve_listbox.delete(0, "end")
        self.curves = []
        self._suspend_auto = False
        self._current_project_path = None
        if prompt_for_path:
            path = self._prompt_project_path()
            if path:
                self._current_project_path = path

    def _curve_label(self, meta: dict, results: dict | None) -> str:
        alignment = meta.get("alignment_name", "Unnamed alignment")
        curve = meta.get("curve_name", "Unnamed curve")
        direction = meta.get("curve_direction", "left")
        inputs = (results or {}).get("inputs", {})
        pc = inputs.get("pc", "?")
        pt = inputs.get("pt", "?")
        speed = inputs.get("speed_mph", "?")
        radius = inputs.get("radius_ft", "?")
        if isinstance(speed, (int, float)) and float(speed).is_integer():
            speed = str(int(speed))
        if isinstance(radius, (int, float)) and float(radius).is_integer():
            radius = str(int(radius))
        return f"{alignment} | {curve} | {direction} | PC {pc} PT {pt} | V {speed} mph | R {radius} ft"

    def _collect_project_data(self) -> dict:
        vars_data: dict[str, object] = {}
        for key, var in self.vars.items():
            if isinstance(var, tk.BooleanVar):
                vars_data[key] = bool(var.get())
            else:
                vars_data[key] = var.get()
        return {
            "version": 1,
            "vars": vars_data,
            "curves": self.curves,
            "last_results": self.last_results,
            "last_meta": self.last_meta,
        }

    def _apply_project_data(self, data: dict) -> None:
        self._suspend_auto = True
        vars_data = data.get("vars", {})
        for key, var in self.vars.items():
            if key not in vars_data:
                continue
            value = vars_data.get(key)
            if isinstance(var, tk.BooleanVar):
                var.set(bool(value))
            else:
                if value is None:
                    var.set("")
                elif isinstance(value, (int, float)) and float(value).is_integer():
                    var.set(str(int(value)))
                else:
                    var.set(str(value))

        self.curve_listbox.delete(0, "end")
        self.curves = []
        for curve in data.get("curves", []) or []:
            if not isinstance(curve, dict):
                continue
            results = curve.get("results")
            meta = curve.get("meta", {}) or {}
            label = self._curve_label(meta, results)
            self.curve_listbox.insert("end", label)
            self.curves.append({"results": results, "meta": meta})

        self.last_results = data.get("last_results")
        self.last_meta = data.get("last_meta", {})
        if self.last_results:
            left_lines, right_lines, table_lines = self._build_display_blocks(self.last_results)
            self._write_output_sections(left_lines, right_lines, table_lines)
        else:
            self._write_output_sections([], [], [])
        self._suspend_auto = False

    def _save_project(self, path: str | None = None, show_dialogs: bool = True) -> bool:
        if path is None:
            path = self._current_project_path
        if path is None:
            path = self._prompt_project_path()
        if not path:
            return False
        data = self._collect_project_data()
        try:
            with open(path, "w", encoding="utf-8") as handle:
                json.dump(data, handle, indent=2)
            self._current_project_path = path
            if show_dialogs:
                messagebox.showinfo("Save Project", f"Saved project to:\n{os.path.basename(path)}")
            return True
        except OSError as exc:
            if show_dialogs:
                messagebox.showerror("Save Project", f"Failed to save project:\n{exc}")
            return False

    def _load_project(self) -> None:
        path = filedialog.askopenfilename(
            filetypes=[("Project files", "*.json")],
            title="Load Project",
        )
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            messagebox.showerror("Load Project", f"Failed to load project:\n{exc}")
            return
        self._apply_project_data(data)
        self._current_project_path = path
        messagebox.showinfo("Load Project", f"Loaded project from:\n{os.path.basename(path)}")

    def _on_close(self) -> None:
        response = messagebox.askyesnocancel(
            "Exit",
            "Save project before exiting?",
        )
        if response is None:
            return
        if response:
            if not self._save_project(show_dialogs=False):
                return
        self.destroy()

    def _add_curve(self) -> None:
        if not self.last_results:
            messagebox.showinfo("Add Curve", "Run a calculation first.")
            return
        alignment = self.vars["alignment_name"].get().strip() or "Unnamed alignment"
        curve = self.vars["curve_name"].get().strip() or "Unnamed curve"
        direction = self.vars["curve_direction"].get().strip() or "left"
        meta = {
            "alignment_name": alignment,
            "curve_name": curve,
            "curve_direction": direction,
        }
        label = self._curve_label(meta, self.last_results)
        self.curve_listbox.insert("end", label)
        self.curves.append({"results": self.last_results, "meta": meta})
        last_idx = self.curve_listbox.size() - 1
        self.curve_listbox.selection_clear(0, "end")
        self.curve_listbox.selection_set(last_idx)

    def _update_selected_curve(self) -> None:
        if not self.last_results:
            messagebox.showinfo("Update Curve", "Run a calculation first.")
            return
        selection = list(self.curve_listbox.curselection())
        if not selection:
            messagebox.showinfo("Update Curve", "Select a curve to update.")
            return
        idx = selection[0]
        if idx >= len(self.curves):
            return
        alignment = self.vars["alignment_name"].get().strip() or "Unnamed alignment"
        curve = self.vars["curve_name"].get().strip() or "Unnamed curve"
        direction = self.vars["curve_direction"].get().strip() or "left"
        meta = {
            "alignment_name": alignment,
            "curve_name": curve,
            "curve_direction": direction,
        }
        label = self._curve_label(meta, self.last_results)
        self.curve_listbox.delete(idx)
        self.curve_listbox.insert(idx, label)
        self.curve_listbox.selection_set(idx)
        self.curves[idx] = {"results": self.last_results, "meta": meta}

    def _remove_curve(self) -> None:
        selection = list(self.curve_listbox.curselection())
        for idx in reversed(selection):
            self.curve_listbox.delete(idx)
            if idx < len(self.curves):
                self.curves.pop(idx)

    def _export_pdf(self) -> None:
        if not self.last_results and not self.curves:
            messagebox.showinfo("Export PDF", "Run a calculation first.")
            return
        try:
            from reportlab.lib.pagesizes import letter
            from reportlab.lib.units import inch
            from reportlab.lib.utils import ImageReader
            from reportlab.pdfgen import canvas
        except Exception as exc:  # pragma: no cover - runtime dependency
            messagebox.showerror(
                "Missing Dependency",
                "ReportLab is required for PDF export.\n"
                "Install it with: python3 -m pip install reportlab",
            )
            return

        diagram_path = None
        diagram_bytes = None
        mdot_bytes = None
        stantec_bytes = None
        if DIAGRAM_PNG_B64:
            try:
                diagram_bytes = base64.b64decode(DIAGRAM_PNG_B64)
            except Exception:
                diagram_bytes = None
        if MDOT_PNG_B64:
            try:
                mdot_bytes = base64.b64decode(MDOT_PNG_B64)
            except Exception:
                mdot_bytes = None
        if STANTEC_PNG_B64:
            try:
                stantec_bytes = base64.b64decode(STANTEC_PNG_B64)
            except Exception:
                stantec_bytes = None
        if diagram_bytes is None:
            diagram_path = filedialog.askopenfilename(
                title="Select Diagram Image (PNG/JPG)",
                filetypes=[("Image files", "*.png;*.jpg;*.jpeg")],
            )
            if not diagram_path:
                return

        path = filedialog.asksaveasfilename(
            defaultextension=".pdf",
            filetypes=[("PDF files", "*.pdf")],
            title="Save PDF",
        )
        if not path:
            return

        curves = self.curves or [{"results": self.last_results, "meta": self.last_meta}]
        stamp_images = self._stamp_images()
        c = canvas.Canvas(path, pagesize=letter)
        width, height = letter

        def lane_signs(direction: str) -> tuple[int, int, str, int]:
            sup_sign = 1 if direction.strip().lower().startswith("r") else -1
            return -1, 1, ("left" if sup_sign == 1 else "right"), sup_sign

        def format_station_ft(value: float | None) -> str:
            if value is None:
                return "n/a"
            return Super.format_station(value, True)

        def build_lane_rows(results: dict, direction: str) -> tuple[list[dict], list[dict]]:
            left_sign, right_sign, runout_lane, sup_sign = lane_signs(direction)
            L = results.get("Lr", 0.0)
            Lt = results.get("Lt", 0.0)
            e = results.get("e", 0.0)
            normal_crown = results.get("inputs", {}).get("normal_crown", 0.02)
            reverse_crown = results.get("reverse_crown_ft", 0.0)
            reverse_crown_out = results.get("reverse_crown_out_ft")

            pc = reverse_crown + 0.7 * L
            full_super_pc = results.get("full_super_ft", 0.0)
            full_super_pt = results.get("full_super_out_ft")
            pt = None
            if reverse_crown_out is not None:
                pt = reverse_crown_out - 0.7 * L

            nc_pct = normal_crown * 100.0
            e_pct = e * 100.0
            e70_pct = e_pct * 0.7

            reverse_crown_case = (
                str(results.get("crown_state", "")).lower().startswith("reverse")
                or str(results.get("e_source", "")).lower().startswith("reverse")
            )
            outside_lane = "right" if direction.strip().lower().startswith("r") else "left"

            def make_row(label: str, station: float | None, slope: float, note: str) -> dict:
                return {
                    "label": label,
                    "station": format_station_ft(station),
                    "slope": f"{slope:.2f}",
                    "note": note,
                }

            def lane_rows(sign: int, has_runout: bool, lane_name: str) -> list[dict]:
                normal_sign = left_sign if lane_name == "left" else right_sign
                rows: list[dict] = []
                if reverse_crown_case:
                    final_slope = (right_sign if outside_lane == "right" else left_sign) * nc_pct
                    is_non_rotating = lane_name == outside_lane
                    start_station = reverse_crown - Lt
                    end_station = None
                    if reverse_crown_out is not None:
                        end_station = reverse_crown_out + Lt

                    if is_non_rotating:
                        rows.append(
                            make_row(
                                "NC",
                                start_station,
                                final_slope,
                                "Sta = PC - 0.7L - Lt (Start rotation)",
                            )
                        )
                        rows.append(make_row("PC", pc, final_slope, "70% super"))
                        rows.append(make_row("FULL SUPER", full_super_pc, final_slope, "Sta = PC + 0.3L"))
                        if pt is not None and full_super_pt is not None:
                            rows.append(make_row("FULL SUPER", full_super_pt, final_slope, "Sta = PT - 0.3L"))
                            rows.append(make_row("PT", pt, final_slope, "70% super"))
                        if end_station is not None:
                            rows.append(make_row("NC", end_station, final_slope, "Sta = PT + 0.7L + Lt"))
                        return rows

                    rows.append(
                        make_row(
                            "NC",
                            start_station,
                            sign * nc_pct,
                            "Sta = PC - 0.7L - Lt (Start rotation)",
                        )
                    )
                    rows.append(make_row("0%", reverse_crown, 0.0, "Sta = PC - 0.7L"))
                    rows.append(make_row("PC", pc, final_slope * 0.7, "70% super"))
                    rows.append(make_row("FULL SUPER", full_super_pc, final_slope, "Sta = PC + 0.3L"))
                    if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                        rows.append(make_row("FULL SUPER", full_super_pt, final_slope, "Sta = PT - 0.3L"))
                        rows.append(make_row("PT", pt, final_slope * 0.7, "70% super"))
                        rows.append(make_row("0%", reverse_crown_out, 0.0, "Sta = PT + 0.7L"))
                        rows.append(
                            make_row(
                                "NC",
                                reverse_crown_out + Lt,
                                sign * nc_pct,
                                "0% + runout (Normal crown)",
                            )
                        )
                    return rows

                if has_runout:
                    rows.append(
                        make_row(
                            "NC",
                            reverse_crown - Lt,
                            normal_sign * nc_pct,
                            "Sta = PC - 0.7L - Lt (Start rotation)",
                        )
                    )
                    rows.append(make_row("0%", reverse_crown, 0.0, "Sta = PC - 0.7L"))
                    rows.append(
                        make_row(
                            "2%",
                            reverse_crown + Lt,
                            sup_sign * nc_pct,
                            "Sta = PC - 0.7L + Lt",
                        )
                    )
                else:
                    rows.append(
                        make_row(
                            "NC",
                            reverse_crown + Lt,
                            normal_sign * nc_pct,
                            "Sta = PC - 0.7L + Lt (Start rotation)",
                        )
                    )

                rows.append(make_row("PC", pc, sup_sign * e70_pct, "70% super"))
                rows.append(make_row("FULL SUPER", full_super_pc, sup_sign * e_pct, "Sta = PC + 0.3L"))
                if pt is not None and full_super_pt is not None and reverse_crown_out is not None:
                    rows.append(make_row("FULL SUPER", full_super_pt, sup_sign * e_pct, "Sta = PT - 0.3L"))
                    rows.append(make_row("PT", pt, sup_sign * e70_pct, "70% super"))
                    if has_runout:
                        rows.append(make_row("0%", reverse_crown_out, 0.0, "Sta = PT + 0.7L"))
                        rows.append(
                            make_row(
                                "NC",
                                reverse_crown_out + Lt,
                                normal_sign * nc_pct,
                                "0% + runout (Normal crown)",
                            )
                        )
                    else:
                        rows.append(
                            make_row(
                                "NC",
                                reverse_crown_out - Lt,
                                normal_sign * nc_pct,
                                "Sta = PT + 0.7L - Lt",
                            )
                        )
                return rows

            left_rows = lane_rows(left_sign, runout_lane == "left", "left")
            right_rows = lane_rows(right_sign, runout_lane == "right", "right")
            return left_rows, right_rows

        def draw_lane_table(c: canvas.Canvas, left: float, y: float, title: str, rows: list[dict]) -> float:
            c.setFont("Helvetica-Bold", 10)
            c.drawString(left, y, title)
            y -= 0.16 * inch

            col_widths = [1.0 * inch, 1.5 * inch, 0.9 * inch, 3.6 * inch]
            row_height = 0.2 * inch
            header_height = 0.22 * inch
            x_positions = [left]
            for width in col_widths:
                x_positions.append(x_positions[-1] + width)

            # Header
            c.setFont("Helvetica-Bold", 8.5)
            c.rect(left, y - header_height, sum(col_widths), header_height, stroke=1, fill=0)
            headers = ["Point", "Station", "Slope (%)", "Note"]
            for idx, header in enumerate(headers):
                c.drawString(x_positions[idx] + 4, y - header_height + 5, header)
            y -= header_height

            c.setFont("Helvetica", 8)
            for row in rows:
                c.rect(left, y - row_height, sum(col_widths), row_height, stroke=1, fill=0)
                c.drawString(x_positions[0] + 4, y - row_height + 5, row["label"])
                c.drawString(x_positions[1] + 4, y - row_height + 5, row["station"])
                c.drawString(x_positions[2] + 4, y - row_height + 5, row["slope"])
                c.drawString(x_positions[3] + 4, y - row_height + 5, row["note"])
                y -= row_height
            return y - 0.2 * inch

        def draw_wrapped_text(
            c: canvas.Canvas,
            text: str,
            x: float,
            y: float,
            max_width: float,
            line_height: float,
            font_name: str,
            font_size: float,
        ) -> float:
            words = text.split()
            if not words:
                c.drawString(x, y, text)
                return y - line_height

            line = ""
            for word in words:
                candidate = f"{line} {word}".strip()
                if c.stringWidth(candidate, font_name, font_size) <= max_width:
                    line = candidate
                else:
                    if line:
                        c.drawString(x, y, line)
                        y -= line_height
                    line = word
            if line:
                c.drawString(x, y, line)
                y -= line_height
            return y

        for idx, curve in enumerate(curves):
            if idx > 0:
                c.showPage()
            results = curve["results"]
            meta = curve.get("meta", {})

            margin = 0.75 * inch
            gap = 0.3 * inch
            right_col_width = 3.1 * inch
            left_col_width = width - (2 * margin + gap + right_col_width)
            left = margin
            right_col_x = left + left_col_width + gap
            title_y = height - margin

            logo_y = None
            logos = []
            max_logo_w = 1.2 * inch
            max_logo_h = 0.6 * inch
            if stantec_bytes:
                stantec_img = ImageReader(io.BytesIO(stantec_bytes))
                sw, sh = stantec_img.getSize()
                scale = min(max_logo_w / sw, max_logo_h / sh)
                logos.append(("stantec", stantec_img, sw * scale, sh * scale))
            if mdot_bytes:
                mdot_img = ImageReader(io.BytesIO(mdot_bytes))
                mw, mh = mdot_img.getSize()
                scale = min(max_logo_w / mw, max_logo_h / mh)
                logos.append(("mdot", mdot_img, mw * scale, mh * scale))

            logo_draws: list[tuple[ImageReader, float, float, float, float]] = []
            if logos:
                logo_gap = 0.08 * inch
                total_w = sum(item[2] for item in logos) + logo_gap * (len(logos) - 1)
                max_h = max(item[3] for item in logos)
                if total_w > right_col_width:
                    factor = right_col_width / total_w
                    logos = [(name, img, w * factor, h * factor) for name, img, w, h in logos]
                    total_w = sum(item[2] for item in logos) + logo_gap * (len(logos) - 1)
                    max_h = max(item[3] for item in logos)

                logo_x = width - margin - total_w
                logo_y = height - margin - max_h + 0.12 * inch
                for name, img, w, h in logos:
                    logo_draws.append((img, logo_x, logo_y, w, h))
                    logo_x += w + logo_gap

            inputs = results.get("inputs", {})
            input_lines = [
                f"Alignment (chain) name: {meta.get('alignment_name', 'n/a')}",
                f"Curve name: {meta.get('curve_name', 'n/a')}",
                f"Curve direction: {meta.get('curve_direction', 'n/a')}",
                f"PC station: {inputs.get('pc', '')}",
                f"PT station: {inputs.get('pt', '') or 'n/a'}",
                f"Design speed: {inputs.get('speed_mph', '')} mph",
                f"Curve radius: {inputs.get('radius_ft', '')} ft",
                f"Facility / rotation: {inputs.get('facility', '')}",
                f"Area type: {inputs.get('area_type', '')}",
                f"Lane width: {inputs.get('lane_width_ft', '')} ft",
                f"Lanes rotated: {inputs.get('lanes_rotated', '')}",
            ]
            longest_label = max(input_lines, key=len)
            left_limit = left + c.stringWidth(longest_label, "Helvetica", 8) + 0.12 * inch

            # Diagram image (right column)
            max_w = width - 2 * margin
            max_h = 2.1 * inch * 1.18
            img_source = diagram_path or io.BytesIO(diagram_bytes)
            img = ImageReader(img_source)
            iw, ih = img.getSize()
            scale = min(max_w / iw, max_h / ih) * 0.8
            img_w, img_h = iw * scale, ih * scale
            center_x = left + (width - 2 * margin) * 0.62
            center_y = title_y - 1.4 * inch
            img_x = center_x - img_w / 2.0
            img_y = center_y - img_h / 2.0
            img_x = max(left, min(img_x, width - margin - img_w))
            img_y = max(margin, min(img_y, height - margin - img_h))
            c.drawImage(img, img_x, img_y, width=img_w, height=img_h, preserveAspectRatio=True)

            for img, x, y_logo, w, h in logo_draws:
                c.drawImage(img, x, y_logo, width=w, height=h, preserveAspectRatio=True)

            stamp_y = img_y - 0.06 * inch
            for stamp_key in self._select_stamps(results):
                stamp_bytes = stamp_images.get(stamp_key)
                if not stamp_bytes:
                    continue
                stamp_img = ImageReader(io.BytesIO(stamp_bytes))
                sw, sh = stamp_img.getSize()
                stamp_scale = min((right_col_width * 0.9) / sw, 0.62)
                stamp_w, stamp_h = sw * stamp_scale, sh * stamp_scale
                stamp_x = right_col_x + (right_col_width - stamp_w) / 2.0
                stamp_y -= stamp_h
                c.drawImage(
                    stamp_img,
                    stamp_x,
                    stamp_y,
                    width=stamp_w,
                    height=stamp_h,
                    preserveAspectRatio=True,
                )
                stamp_y -= 0.07 * inch
            stamp_bottom = stamp_y

            # Title
            c.setFont("Helvetica-Bold", 14)
            c.drawString(left, title_y, "Superelevation Transition Summary")

            # Sections
            y = title_y - 0.30 * inch
            c.setFont("Helvetica-Bold", 11)
            c.drawString(left, y, "Inputs")
            y -= 0.20 * inch

            c.setFont("Helvetica", 8)
            for line in input_lines:
                y = draw_wrapped_text(
                    c,
                    line,
                    left,
                    y,
                    left_col_width,
                    0.13 * inch,
                    "Helvetica",
                    8,
                )

            y -= 0.08 * inch
            c.setFont("Helvetica-Bold", 11)
            c.drawString(left, y, "Givens")
            y -= 0.20 * inch

            notes = []
            if results.get("friction_note"):
                notes.append(results["friction_note"])
            if results.get("rel_grad_note"):
                notes.append(results["rel_grad_note"])
            if results.get("lanes_note"):
                notes.append(results["lanes_note"])
            if results.get("r_note"):
                notes.append(results["r_note"])
            if results.get("e_note"):
                notes.append(results["e_note"])
            if results.get("runoff_note"):
                notes.append(results["runoff_note"])
            if results.get("extra_width_note"):
                notes.append(results["extra_width_note"])

            givens_lines = [
                f"Facility case: {results.get('facility', '')}",
                f"PT: {inputs.get('pt', '') or 'n/a'}",
                f"e_max used: {results.get('e_max', 0):.2f} ft/ft",
                f"e source: {results.get('e_source', '')}",
                f"Lanes rotated used: {results.get('lanes_used', 0):.1f} (n1={results.get('n1', 0):.1f}, bw={results.get('bw', 0):.3f})",
                f"Relative gradient used: {results.get('relative_gradient', 0):.4f} ft/ft",
                f"Note: {', '.join(notes) if notes else 'n/a'}",
                f"Table 3-4-A radii (Rnc, Rrc): {results.get('r_normal', 0):.0f} ft, {results.get('r_reverse', 0):.0f} ft",
                f"Crown condition: {results.get('crown_state', '')}",
            ]
            c.setFont("Helvetica", 8)
            for line in givens_lines:
                y = draw_wrapped_text(
                    c,
                    line,
                    left,
                    y,
                    left_col_width,
                    0.13 * inch,
                    "Helvetica",
                    8,
                )

            y -= 0.08 * inch
            c.setFont("Helvetica-Bold", 11)
            c.drawString(left, y, "Results")
            y -= 0.20 * inch

            c.setFont("Helvetica-Bold", 9)
            results_lines = [
                f"Super rate (e): {results.get('e', 0):.4f} ft/ft",
                f"Design speed: {inputs.get('speed_mph', '')} mph",
                f"Tangent runoff length Lr: {results.get('Lr', 0):.2f} ft",
                f"Tangent runout length Lt: {results.get('Lt', 0):.2f} ft",
            ]
            if results.get("extra_width", 0.0) > 0:
                results_lines.append(
                    f"Extra width (inside of curve): {results.get('extra_width', 0):.2f} ft"
                )
            for line in results_lines:
                if line.startswith("Extra width"):
                    c.setFillColorRGB(0.8, 0.0, 0.0)
                    c.drawString(left, y, line)
                    c.setFillColorRGB(0.0, 0.0, 0.0)
                else:
                    c.drawString(left, y, line)
                y -= 0.14 * inch

            y -= 0.10 * inch
            min_table_y = img_y - 0.2 * inch
            if stamp_bottom is not None:
                min_table_y = min(min_table_y, stamp_bottom - 0.12 * inch)
            if y > min_table_y:
                y = min_table_y
            left_rows, right_rows = build_lane_rows(results, meta.get("curve_direction", "left"))
            y = draw_lane_table(c, left, y, "Left Lane", left_rows)
            y = draw_lane_table(c, left, y, "Right Lane", right_rows)

        c.save()
        messagebox.showinfo("Export PDF", f"Saved PDF to:\n{os.path.basename(path)}")
        if self.vars["auto_open_pdf"].get():
            self._open_file(path)

    def _open_file(self, path: str) -> None:
        try:
            if os.name == "nt":
                os.startfile(path)
            elif sys.platform == "darwin":
                subprocess.run(["open", path], check=False)
            else:
                subprocess.run(["xdg-open", path], check=False)
        except Exception:
            messagebox.showwarning("Open PDF", f"Saved PDF to:\n{path}")

    def _stamp_images(self) -> dict[str, bytes]:
        images: dict[str, bytes] = {}
        for key, value in STAMP_PNG_B64.items():
            try:
                images[key] = base64.b64decode(value)
            except Exception:
                continue
        return images

    def _select_stamps(self, results: dict) -> list[str]:
        inputs = results.get("inputs", {})
        area = str(inputs.get("area_type", "")).lower()
        facility = str(inputs.get("facility", "")).lower()
        speed = inputs.get("speed_mph", 0)
        stamps: list[str] = []

        if area.startswith("local"):
            if "SE-1" in STAMP_PNG_B64:
                stamps.append("SE-1")
        elif area.startswith("urban"):
            if speed <= 45 and "center" in facility:
                if "SE-2E" in STAMP_PNG_B64:
                    stamps.append("SE-2E")
            elif speed == 50 and "center" in facility:
                if "SE-2C" in STAMP_PNG_B64:
                    stamps.append("SE-2C")
            elif speed == 50 and "edge" in facility:
                if "SE-2D" in STAMP_PNG_B64:
                    stamps.append("SE-2D")
        else:
            if "edge" in facility:
                if "SE-2B" in STAMP_PNG_B64:
                    stamps.append("SE-2B")
                if "SE-3B" in STAMP_PNG_B64:
                    stamps.append("SE-3B")
            else:
                if "SE-2A" in STAMP_PNG_B64:
                    stamps.append("SE-2A")
                if "SE-3A" in STAMP_PNG_B64:
                    stamps.append("SE-3A")
        return stamps


